-- LytHouse launch reconciliation (additive / non-destructive)
CREATE TABLE IF NOT EXISTS public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,description text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL DEFAULT 'member',created_at timestamptz DEFAULT now(),UNIQUE(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,name text NOT NULL,description text,git_url text NOT NULL,git_branch text NOT NULL,repo_folder text NOT NULL,github_token text,language text,framework text,status text NOT NULL DEFAULT 'active',created_by uuid DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz DEFAULT now());
ALTER TABLE public.projects ADD COLUMN IF NOT EXISTS github_token text;
CREATE TABLE IF NOT EXISTS public.validations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'pending',trigger text NOT NULL DEFAULT 'manual',commit_sha text,risk_score integer,severity text,summary text,total_findings integer NOT NULL DEFAULT 0,critical_count integer NOT NULL DEFAULT 0,high_count integer NOT NULL DEFAULT 0,medium_count integer NOT NULL DEFAULT 0,low_count integer NOT NULL DEFAULT 0,duration_ms integer,created_by uuid DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE SET NULL,created_at timestamptz DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.validation_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),validation_id uuid NOT NULL REFERENCES public.validations(id) ON DELETE CASCADE,step_index integer NOT NULL,key text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'pending',detail text,duration_ms integer,created_at timestamptz DEFAULT now(),started_at timestamptz,completed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),validation_id uuid NOT NULL REFERENCES public.validations(id) ON DELETE CASCADE,project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,category text NOT NULL,severity text NOT NULL,title text NOT NULL,description text NOT NULL,file_path text,line integer,recommendation text,confidence integer,status text NOT NULL DEFAULT 'open',resolution_note text,resolved_at timestamptz,created_at timestamptz DEFAULT now());
ALTER TABLE public.findings ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'open'; ALTER TABLE public.findings ADD COLUMN IF NOT EXISTS resolution_note text; ALTER TABLE public.findings ADD COLUMN IF NOT EXISTS resolved_at timestamptz;
CREATE TABLE IF NOT EXISTS public.workspace_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid UNIQUE NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,plan_id text NOT NULL DEFAULT 'free' CHECK(plan_id IN ('free','developer','enterprise')),status text NOT NULL DEFAULT 'active',trial_ends_at timestamptz,current_period_end timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,action text NOT NULL,entity_type text,entity_id text,metadata jsonb DEFAULT '{}'::jsonb,ip_address text,user_agent text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.release_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,validation_id uuid REFERENCES public.validations(id) ON DELETE SET NULL,release_name text NOT NULL,status text NOT NULL DEFAULT 'pending',required_approvers text[] DEFAULT '{}',approvals jsonb DEFAULT '[]'::jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.environment_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,provider text NOT NULL,name text,status text NOT NULL DEFAULT 'disconnected',config jsonb DEFAULT '{}'::jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY; ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY; ALTER TABLE public.validations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.validation_steps ENABLE ROW LEVEL SECURITY; ALTER TABLE public.findings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workspace_plans ENABLE ROW LEVEL SECURITY; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.release_approvals ENABLE ROW LEVEL SECURITY; ALTER TABLE public.environment_connections ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_lythouse_workspace_member(ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=ws AND w.owner_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=ws AND m.user_id=auth.uid()); $$;
DROP POLICY IF EXISTS lythouse_workspaces_select ON public.workspaces; CREATE POLICY lythouse_workspaces_select ON public.workspaces FOR SELECT TO authenticated USING(public.is_lythouse_workspace_member(id));
DROP POLICY IF EXISTS lythouse_workspaces_insert ON public.workspaces; CREATE POLICY lythouse_workspaces_insert ON public.workspaces FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
DROP POLICY IF EXISTS lythouse_workspaces_update ON public.workspaces; CREATE POLICY lythouse_workspaces_update ON public.workspaces FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
DROP POLICY IF EXISTS lythouse_workspaces_delete ON public.workspaces; CREATE POLICY lythouse_workspaces_delete ON public.workspaces FOR DELETE TO authenticated USING(owner_id=auth.uid());
DROP POLICY IF EXISTS lythouse_members_select ON public.workspace_members; CREATE POLICY lythouse_members_select ON public.workspace_members FOR SELECT TO authenticated USING(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_members_write ON public.workspace_members; CREATE POLICY lythouse_members_write ON public.workspace_members FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=workspace_id AND w.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=workspace_id AND w.owner_id=auth.uid()));
DROP POLICY IF EXISTS lythouse_projects_access ON public.projects; CREATE POLICY lythouse_projects_access ON public.projects FOR ALL TO authenticated USING(public.is_lythouse_workspace_member(workspace_id)) WITH CHECK(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_validations_access ON public.validations; CREATE POLICY lythouse_validations_access ON public.validations FOR ALL TO authenticated USING(public.is_lythouse_workspace_member(workspace_id)) WITH CHECK(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_steps_access ON public.validation_steps; CREATE POLICY lythouse_steps_access ON public.validation_steps FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.validations v WHERE v.id=validation_id AND public.is_lythouse_workspace_member(v.workspace_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.validations v WHERE v.id=validation_id AND public.is_lythouse_workspace_member(v.workspace_id)));
DROP POLICY IF EXISTS lythouse_findings_access ON public.findings; CREATE POLICY lythouse_findings_access ON public.findings FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.validations v WHERE v.id=validation_id AND public.is_lythouse_workspace_member(v.workspace_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.validations v WHERE v.id=validation_id AND public.is_lythouse_workspace_member(v.workspace_id)));
DROP POLICY IF EXISTS lythouse_workspace_plans_select ON public.workspace_plans; CREATE POLICY lythouse_workspace_plans_select ON public.workspace_plans FOR SELECT TO authenticated USING(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_audit_select ON public.audit_logs; CREATE POLICY lythouse_audit_select ON public.audit_logs FOR SELECT TO authenticated USING(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_audit_insert ON public.audit_logs; CREATE POLICY lythouse_audit_insert ON public.audit_logs FOR INSERT TO authenticated WITH CHECK(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_release_approvals_access ON public.release_approvals; CREATE POLICY lythouse_release_approvals_access ON public.release_approvals FOR ALL TO authenticated USING(public.is_lythouse_workspace_member(workspace_id)) WITH CHECK(public.is_lythouse_workspace_member(workspace_id));
DROP POLICY IF EXISTS lythouse_environment_connections_access ON public.environment_connections; CREATE POLICY lythouse_environment_connections_access ON public.environment_connections FOR ALL TO authenticated USING(public.is_lythouse_workspace_member(workspace_id)) WITH CHECK(public.is_lythouse_workspace_member(workspace_id));
CREATE OR REPLACE FUNCTION public.create_lythouse_free_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.workspace_plans(workspace_id,plan_id,status) VALUES(NEW.id,'free','active') ON CONFLICT(workspace_id) DO NOTHING; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS on_lythouse_workspace_created ON public.workspaces; CREATE TRIGGER on_lythouse_workspace_created AFTER INSERT ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.create_lythouse_free_plan();
CREATE INDEX IF NOT EXISTS idx_lythouse_workspaces_owner ON public.workspaces(owner_id); CREATE INDEX IF NOT EXISTS idx_lythouse_members_user ON public.workspace_members(user_id); CREATE INDEX IF NOT EXISTS idx_lythouse_projects_workspace ON public.projects(workspace_id); CREATE INDEX IF NOT EXISTS idx_lythouse_validations_project ON public.validations(project_id); CREATE INDEX IF NOT EXISTS idx_lythouse_findings_validation ON public.findings(validation_id);